/// <summary>ConcurrentDictionary&lt;TKey, TValue&gt;(書き込み時点のスナップショット)。</summary>
public readonly struct ConcurrentDictionaryFormatter<TKey, TValue, FK, FV> : IApexFormatter<ConcurrentDictionary<TKey, TValue>?>
    where TKey : notnull
    where FK : IApexFormatter<TKey>
    where FV : IApexFormatter<TValue>
{
    public static void Write<TWriter, TTracker>(ref TWriter writer, scoped in ConcurrentDictionary<TKey, TValue>? value, ref TTracker tracker)
        where TWriter : struct, IApexBufferWriter, allows ref struct
        where TTracker : IReferenceTracker, allows ref struct
    {
        if (value is null) { writer.WriteNullCollectionHeader(); return; }
        var snapshot = value.ToArray();
        writer.WriteCollectionHeader(snapshot.Length);
        foreach (var pair in snapshot) { TKey key = pair.Key; TValue item = pair.Value; FK.Write(ref writer, in key, ref tracker); FV.Write(ref writer, in item, ref tracker); }
    }

    public static ConcurrentDictionary<TKey, TValue>? Read<TReader, TTracker, TGuard>(ref TReader reader, ref TTracker tracker, ref TGuard guard)
        where TReader : struct, IApexBufferReader, allows ref struct
        where TTracker : IReferenceTracker, allows ref struct
        where TGuard : ISecurityGuard, allows ref struct
    {
        uint header = reader.ReadCompactUInt(); if (header == 0) return null; int count = DictionaryHelper.CheckCount(ref reader, ref guard, header - 1, FK.MinWireSize + FV.MinWireSize);
        var dictionary = new ConcurrentDictionary<TKey, TValue>(Environment.ProcessorCount, count);
        for (int i = 0; i < count; i++)
        {
            TKey key = FK.Read(ref reader, ref tracker, ref guard);
            TValue item = FV.Read(ref reader, ref tracker, ref guard);
            dictionary.TryAdd(key, item);
        }
        return dictionary;
    }
}

