/// <summary>PriorityQueue&lt;TElement, TPriority&gt;(要素と優先度の組。順序は保存しない)。</summary>
public readonly struct PriorityQueueFormatter<TKey, TValue, FK, FV> : IApexFormatter<PriorityQueue<TKey, TValue>?>
    where FK : IApexFormatter<TKey>
    where FV : IApexFormatter<TValue>
{
    public static void Write<TWriter, TTracker>(ref TWriter writer, scoped in PriorityQueue<TKey, TValue>? value, ref TTracker tracker)
        where TWriter : struct, IApexBufferWriter, allows ref struct
        where TTracker : IReferenceTracker, allows ref struct
    {
        if (value is null) { writer.WriteNullCollectionHeader(); return; }
        writer.WriteCollectionHeader(value.UnorderedItems.Count);
        foreach (var (element, priority) in value.UnorderedItems) { TKey key = element; TValue item = priority; FK.Write(ref writer, in key, ref tracker); FV.Write(ref writer, in item, ref tracker); }
    }

    public static PriorityQueue<TKey, TValue>? Read<TReader, TTracker, TGuard>(ref TReader reader, ref TTracker tracker, ref TGuard guard)
        where TReader : struct, IApexBufferReader, allows ref struct
        where TTracker : IReferenceTracker, allows ref struct
        where TGuard : ISecurityGuard, allows ref struct
    {
        uint header = reader.ReadCompactUInt(); if (header == 0) return null; int count = DictionaryHelper.CheckCount(ref reader, ref guard, header - 1, FK.MinWireSize + FV.MinWireSize);
        var dictionary = new PriorityQueue<TKey, TValue>(count);
        for (int i = 0; i < count; i++)
        {
            TKey key = FK.Read(ref reader, ref tracker, ref guard);
            TValue item = FV.Read(ref reader, ref tracker, ref guard);
            dictionary.Enqueue(key, item);
        }
        return dictionary;
    }
}
